api_mappings.custom_func_imp:
const NppLibraryVersion *  nppGetLibVersion() {
    // TraceCall("nppGetLibVersion");
    static const NppLibraryVersion hgppVer = {NPP_VER_MAJOR, NPP_VER_MINOR, NPP_VER_BUILD};
    return &hgppVer;
}

global_custom_code.loader_start:
static uint32_t g_profileDomain;

static const char* g_profileFunctionList[] = {
    "nppGetLibVersion",
};

enum nppcProfileCallbackId {
    nppc_TRACE_CBID_nppGetLibVersion = 0,
};

typedef uint32_t (*nppcRegisterProfileDomain)(const char* domain_name, const char** function_list, uint32_t function_number);
typedef uint8_t (*nppcIsProfileCallbackEnabled)(uint32_t domain, uint32_t callback_id);
typedef void (*nppcProfileCallbackBegin)(uint32_t domain, uint32_t callback_id);
typedef void (*nppcProfileCallbackEnd)(uint32_t domain, uint32_t callback_id);

struct nppcProfileHandler {
    nppcRegisterProfileDomain registerProfileDomain;
    nppcIsProfileCallbackEnabled isCallbackEnabled;
    nppcProfileCallbackBegin profileCallbackBegin;
    nppcProfileCallbackEnd profileCallbackEnd;
};

static nppcProfileHandler g_profileHandler;
static bool gDirectReturn = false;
static const char* gLibName = "nppc";

static void InitializeProfileHandler() {
    // get library patch
    const char* profile_tool_library = getenv("WRAPPER_INJECTION_PATH");
    if (profile_tool_library == NULL) {
        return;
    }

    // open profile library
    void* tool_handler = dlopen(profile_tool_library, RTLD_LAZY);
    if (!tool_handler) {
        printf("cannot open the file:%s  with error %s\n", profile_tool_library, dlerror());
        return;
    }

    // init profile handler
    g_profileHandler.registerProfileDomain = reinterpret_cast<nppcRegisterProfileDomain>(dlsym(tool_handler, "wrapperRegisterProfileDomain"));
    g_profileHandler.isCallbackEnabled = reinterpret_cast<nppcIsProfileCallbackEnabled>(dlsym(tool_handler, "wrapperIsProfileCallbackEnabled"));
    g_profileHandler.profileCallbackBegin = reinterpret_cast<nppcProfileCallbackBegin>(dlsym(tool_handler, "wrapperProfileCallbackBegin"));
    g_profileHandler.profileCallbackEnd = reinterpret_cast<nppcProfileCallbackEnd>(dlsym(tool_handler, "wrapperProfileCallbackEnd"));

    // register profile domain
    if (g_profileHandler.registerProfileDomain != NULL) {
        g_profileDomain = g_profileHandler.registerProfileDomain(gLibName, g_profileFunctionList, sizeof(g_profileFunctionList) / sizeof(g_profileFunctionList[0]));
        if (g_profileDomain == 0) {
            g_profileHandler.isCallbackEnabled = NULL;
        }
    }
}

global_custom_code.pre_wrapper_call:
bool needProfile = g_profileHandler.isCallbackEnabled != NULL &&
    g_profileHandler.isCallbackEnabled(g_profileDomain, nppc_TRACE_CBID_$WRAPPER_FUNC_NAME) != 0;
if (needProfile) {
    g_profileHandler.profileCallbackBegin(g_profileDomain, nppc_TRACE_CBID_$WRAPPER_FUNC_NAME);
}
